//! Gallery's commands, as Windows 11 File Explorer's Gallery has them: the
//! command bar with Sort grayed and Collection, photo commands while a
//! photo is selected, the View and Collection menus, the "Gallery
//! Locations" dialog, a photo's right-click menu and Rotate.
//!
//! Every picture here is generated by the test (flat colours, no people)
//! and every folder name is fictional.

use std::fs;

use gtk::gdk_pixbuf::Pixbuf;
use gtk::prelude::*;
use ox_core::location::file_uri;

use super::gallery::{gallery_window, set_modified, PicturesHome};
use super::support::menu_button_with_class;
use crate::test_support::harness::{wait_until, TestWindow};
use crate::test_support::pictures::{jpeg_bytes, png_sized};
use crate::folder_view::icon_size::IconSize;
use crate::window::folder_pane::FolderView;
use crate::window::gallery_locations::GalleryLocations;
use crate::window::menu_popover::MenuPopover;

/// The command bar's shown commands in order, each with whether it can
/// be used now; menus by their label, icon commands by their name.
fn commands(test: &TestWindow) -> Vec<(String, bool)> {
    test.window.command_bar().shown_commands()
}

/// The menu a command bar button with `class` opens, opened.
fn open_menu(test: &TestWindow, class: &str) -> MenuPopover {
    let button = menu_button_with_class(test, class);
    let menu = button.popover().and_downcast::<MenuPopover>().expect("a menu");
    button.popup();
    wait_until("the menu", || menu.is_visible());
    menu
}

fn close(menu: &MenuPopover) {
    menu.popdown();
    wait_until("the menu to close", || !menu.is_visible());
}

/// A Gallery of one PNG photo, `a.png`.
fn one_photo() -> (PicturesHome, TestWindow) {
    let home = PicturesHome::new();
    let path = home.pictures().join("a.png");
    fs::write(&path, png_sized(120, 80, 0x0055_7799)).expect("a photo");
    set_modified(&path, "2026-11-02");
    let test = gallery_window(&home);
    (home, test)
}

/// Gallery's command bar: New grayed, Cut, Copy, Paste, Rename, Share,
/// Delete, Sort grayed, View, Collection and "…"; a selected photo adds
/// Set as background, Rotate left and Rotate right.
///
/// parity: HOME-030
#[gtk::test]
fn the_command_bar_grays_sort_and_offers_photo_commands_for_a_photo() {
    let (_home, test) = one_photo();
    let names =
        |test: &TestWindow| -> Vec<String> { commands(test).into_iter().map(|(name, _)| name).collect() };
    let shown = commands(&test);
    let labels = names(&test);
    let at = |label: &str| {
        shown
            .iter()
            .find(|(name, _)| name == label)
            .unwrap_or_else(|| panic!("{label} shows: {shown:?}"))
            .1
    };
    assert!(!at("New"), "New is grayed: {shown:?}");
    assert!(!at("Sort"), "Sort is grayed: {shown:?}");
    assert!(at("View"));
    assert!(at("Collection"));
    let order: Vec<&str> = [
        "New",
        "Cut",
        "Copy",
        "Paste",
        "Rename",
        "Delete",
        "Sort",
        "View",
        "Collection",
        "See more",
    ]
    .into_iter()
    .filter(|label| labels.iter().any(|shown| shown == label))
    .collect();
    let positions: Vec<usize> = order
        .iter()
        .map(|label| labels.iter().position(|shown| shown == label).expect("shown"))
        .collect();
    assert!(positions.windows(2).all(|pair| pair[0] < pair[1]), "{labels:?}");
    assert_eq!(order.len(), 10, "{labels:?}");
    for photo_command in ["Set as background", "Rotate left", "Rotate right"] {
        assert!(!labels.iter().any(|label| label == photo_command), "{labels:?}");
    }

    test.select_named("a.png");
    wait_until("the photo commands", || {
        names(&test).iter().any(|label| label == "Rotate right")
    });
    let labels = names(&test);
    let collection = labels
        .iter()
        .position(|label| label == "Collection")
        .expect("Collection");
    let rotate_left = labels
        .iter()
        .position(|label| label == "Rotate left")
        .expect("Rotate left");
    let rotate_right = labels
        .iter()
        .position(|label| label == "Rotate right")
        .expect("Rotate right");
    let background = labels
        .iter()
        .position(|label| label == "Set as background")
        .expect("background");
    assert!(
        collection < background && background < rotate_left && rotate_left < rotate_right,
        "{labels:?}"
    );

    test.window.navigate(&file_uri(&_home.home)).expect("home");
    test.wait_for_listing("the home folder");
    assert!(commands(&test)
        .iter()
        .any(|(label, usable)| label == "Sort" && *usable));
}

/// Gallery's View menu offers the four icon sizes, Medium icons chosen,
/// then the Details and Preview panes and Show; no other layout.
///
/// parity: HOME-031
#[gtk::test]
fn the_view_menu_offers_only_the_icon_sizes_and_the_panes() {
    let (_home, test) = one_photo();
    let menu = open_menu(&test, "view-command");
    assert_eq!(
        menu.items_labels(),
        [
            "Extra large icons",
            "Large icons",
            "Medium icons",
            "Small icons",
            "Details pane",
            "Preview pane",
            "Show",
        ]
    );
    assert!(menu.checked_labels().contains(&"Medium icons".to_owned()));
    close(&menu);

    // Ctrl+wheel steps through the four sizes only, and the other layouts'
    // keys and buttons change nothing.
    let view = || test.window.folder_pane().view();
    test.window.zoom_view(1);
    assert_eq!(view(), FolderView::Icons(IconSize::LARGE));
    test.window.zoom_view(4);
    assert_eq!(view(), FolderView::Icons(IconSize::EXTRA_LARGE));
    test.window.zoom_view(-9);
    assert_eq!(view(), FolderView::Icons(IconSize::SMALL));
    test.window.zoom_view(-1);
    assert_eq!(view(), FolderView::Icons(IconSize::SMALL));
    for other in ["details", "compact", "tiles", "content"] {
        test.activate("view", Some(other));
        assert_eq!(view(), FolderView::Icons(IconSize::SMALL), "{other}");
    }
    test.activate("view", Some("medium"));
    assert_eq!(view(), FolderView::Icons(IconSize::MEDIUM));
}

/// The Collection menu: "Show all" chosen, one row per location, then
/// "Manage collection".
///
/// parity: HOME-025
#[gtk::test]
fn the_collection_menu_shows_all_each_location_and_manage_collection() {
    let (_home, test) = one_photo();
    let menu = open_menu(&test, "collection-command");
    assert_eq!(menu.items_labels(), ["Show all", "Pictures", "Manage collection"]);
    assert_eq!(menu.checked_labels(), ["Show all"]);
    close(&menu);
}

/// The dialog Manage collection opens.
fn locations_dialog(test: &TestWindow) -> GalleryLocations {
    test.activate("gallery-manage", None);
    wait_until("Gallery Locations", || test.window.gallery_locations().is_some());
    let dialog = test.window.gallery_locations().expect("the dialog");
    wait_until("the dialog shows", || dialog.is_visible());
    dialog
}

/// "Gallery Locations": its heading, text and list, with Pictures as the
/// default save location that cannot be removed; Add… adds a folder,
/// Remove removes one added, OK keeps the list and Cancel drops the
/// changes.
///
/// parity: HOME-025
#[gtk::test]
fn gallery_locations_adds_and_removes_folders_and_ok_keeps_them() {
    let (home, test) = one_photo();
    let camera = home.home.join("Camera imports");
    fs::create_dir_all(&camera).expect("a folder");
    fs::write(
        camera.join("dune.jpg"),
        jpeg_bytes(0x0022_4466, Some("2026:10:01 10:00:00")),
    )
    .expect("a photo");

    let dialog = locations_dialog(&test);
    assert_eq!(dialog.title().as_deref(), Some("Gallery Locations"));
    assert_eq!(dialog.heading_text(), "Choose which folders to see in Gallery");
    assert!(dialog
        .body_text()
        .starts_with("Manage your Gallery by adding or removing folders"));
    assert!(dialog
        .body_text()
        .contains("will still be stored in their original locations"));
    assert_eq!(dialog.list_label(), "Gallery locations");
    let pictures = home.pictures().display().to_string();
    assert_eq!(
        dialog.rows(),
        [(
            "Pictures".to_owned(),
            pictures.clone(),
            "Default save location".to_owned()
        )]
    );
    dialog.select_row(0);
    assert!(!dialog.can_remove(), "Pictures cannot be removed");

    // Cancel drops an added folder.
    dialog.add_folder(&file_uri(&camera));
    assert_eq!(dialog.rows().len(), 2);
    dialog.cancel();
    wait_until("the dialog to close", || {
        test.window.gallery_locations().is_none()
    });
    assert_eq!(test.names(), ["a.png"]);

    // OK keeps it, in Gallery and in the settings file.
    let dialog = locations_dialog(&test);
    assert_eq!(dialog.rows().len(), 1);
    dialog.add_folder(&file_uri(&camera));
    dialog.ok();
    wait_until("the added folder's photo", || test.names().len() == 2);
    wait_until("the folder saved", || {
        fs::read_to_string(test.settings_directory().join("settings.json"))
            .unwrap_or_default()
            .contains("Camera%20imports")
    });
    let menu = open_menu(&test, "collection-command");
    assert_eq!(
        menu.items_labels(),
        ["Show all", "Pictures", "Camera imports", "Manage collection"]
    );
    close(&menu);

    // Remove takes it out again.
    let dialog = locations_dialog(&test);
    assert_eq!(dialog.rows()[1].0, "Camera imports");
    dialog.select_row(1);
    assert!(dialog.can_remove());
    dialog.remove_selected();
    assert_eq!(dialog.rows().len(), 1);
    dialog.ok();
    wait_until("the removed folder to leave", || test.names() == ["a.png"]);
}

/// Choosing a location in Collection shows only its photos; Show all
/// shows every location again.
///
/// parity: HOME-025
#[gtk::test]
fn choosing_a_location_shows_only_its_photos() {
    let (home, test) = one_photo();
    let camera = home.home.join("Camera imports");
    fs::create_dir_all(&camera).expect("a folder");
    fs::write(
        camera.join("dune.jpg"),
        jpeg_bytes(0x0022_4466, Some("2026:10:01 10:00:00")),
    )
    .expect("a photo");
    let dialog = locations_dialog(&test);
    dialog.add_folder(&file_uri(&camera));
    dialog.ok();
    wait_until("both folders", || test.names().len() == 2);

    let menu = open_menu(&test, "collection-command");
    menu.click_row("Camera imports");
    wait_until("only the added folder", || test.names() == ["dune.jpg"]);
    let menu = open_menu(&test, "collection-command");
    assert_eq!(menu.checked_labels(), ["Camera imports"]);
    menu.click_row("Show all");
    wait_until("every folder again", || test.names().len() == 2);
}

/// A photo's right-click menu is Windows 11's: Cut, Copy, Share and
/// Delete in the strip, then Open, Open with, Share with, Set as desktop
/// background, Rotate right, Rotate left, Open file location, Add to
/// Favorites, Compress to, Copy as path, Properties and Show more
/// options.
///
/// parity: HOME-022
#[gtk::test]
fn a_photos_menu_is_windows_galleries() {
    let (_home, test) = one_photo();
    test.window.right_click(Some(0));
    let menu = test.window.context_menu();
    wait_until("the menu", || menu.is_visible());
    let labels = menu.items_labels();
    let expected = [
        "Open",
        "Open with",
        "Set as desktop background",
        "Rotate right",
        "Rotate left",
        "Open file location",
        "Add to Favorites",
        "Compress to",
        "Copy as path",
        "Properties",
        "Show more options",
    ];
    // Without applications for PNG files, Open with asks for one.
    let shown: Vec<&str> = labels
        .iter()
        .map(|label| {
            if label == "Open with…" {
                "Open with"
            } else {
                label.as_str()
            }
        })
        .filter(|label| *label != "Share with")
        .collect();
    assert_eq!(shown, expected, "{labels:?}");
    let strip = menu.strip_labels();
    let strip: Vec<&str> = strip
        .iter()
        .map(String::as_str)
        .filter(|label| *label != "Share")
        .collect();
    assert_eq!(strip, ["Cut", "Copy", "Delete"]);
}

/// The EXIF orientation of the JPEG at `path`, if it has one.
fn orientation(path: &std::path::Path) -> Option<u32> {
    let bytes = fs::read(path).ok()?;
    let exif = exif::Reader::new()
        .read_from_container(&mut std::io::Cursor::new(bytes))
        .ok()?;
    exif.get_field(exif::Tag::Orientation, exif::In::PRIMARY)?
        .value
        .get_uint(0)
}

/// Rotate right and Rotate left turn a JPEG by its EXIF orientation,
/// leaving its pixels as they are, and a PNG by its pixels; the photo
/// keeps its name and place.
///
/// parity: HOME-032
#[gtk::test]
fn rotate_turns_jpegs_by_their_orientation_and_pngs_by_their_pixels() {
    let home = PicturesHome::new();
    let jpeg = home.pictures().join("pier.jpg");
    fs::write(&jpeg, jpeg_bytes(0x0011_2233, Some("2026:10:01 10:00:00"))).expect("a JPEG");
    let plain = home.pictures().join("plain.jpg");
    fs::write(&plain, jpeg_bytes(0x0011_2233, None)).expect("a JPEG without EXIF");
    let png = home.pictures().join("chart.png");
    fs::write(&png, png_sized(120, 40, 0x0066_8800)).expect("a PNG");
    let test = gallery_window(&home);
    let scan_bytes = |path: &std::path::Path| {
        let bytes = fs::read(path).expect("the file");
        let start = bytes
            .windows(2)
            .position(|pair| pair == [0xff, 0xda])
            .expect("a scan");
        bytes[start..].to_vec()
    };
    let scan = scan_bytes(&jpeg);

    test.select_named("pier.jpg");
    test.activate("rotate-right", None);
    wait_until("orientation 6", || orientation(&jpeg) == Some(6));
    assert_eq!(scan_bytes(&jpeg), scan, "the pixels are left as they are");
    test.activate("rotate-right", None);
    wait_until("orientation 3", || orientation(&jpeg) == Some(3));
    test.activate("rotate-left", None);
    test.activate("rotate-left", None);
    wait_until("orientation 1", || orientation(&jpeg) == Some(1));
    assert!(orientation(&jpeg).is_some());

    test.select_named("plain.jpg");
    test.activate("rotate-left", None);
    wait_until("orientation 8", || orientation(&plain) == Some(8));

    test.select_named("chart.png");
    test.activate("rotate-right", None);
    wait_until("the PNG turned", || {
        Pixbuf::from_file(&png).is_ok_and(|picture| picture.width() == 40 && picture.height() == 120)
    });
    wait_until("still listed", || test.names().len() == 3);
}

/// Set as desktop background shows, grayed: the app has no way to set
/// the desktop's background yet.
///
/// parity: HOME-030
#[gtk::test]
fn set_as_background_shows_grayed() {
    let (_home, test) = one_photo();
    test.select_named("a.png");
    wait_until("the photo commands", || {
        commands(&test)
            .iter()
            .any(|(label, _)| label == "Set as background")
    });
    let shown = commands(&test);
    let (_, usable) = shown
        .iter()
        .find(|(label, _)| label == "Set as background")
        .expect("Set as background");
    assert!(!usable, "{shown:?}");
    let rotate = shown
        .iter()
        .find(|(label, _)| label == "Rotate right")
        .expect("Rotate right");
    assert!(rotate.1);
}
